CREATE TABLE risk_rules (rule_id UUID PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, owner TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE risk_rule_versions (version_id UUID PRIMARY KEY, rule_id UUID NOT NULL REFERENCES risk_rules(rule_id), version TEXT NOT NULL, stage TEXT NOT NULL, scope TEXT NOT NULL, metric TEXT NOT NULL, operator TEXT NOT NULL, threshold JSONB NOT NULL, severity TEXT NOT NULL, effective_from DATE NOT NULL, effective_to DATE, owner TEXT NOT NULL, exception_allowed BOOLEAN NOT NULL DEFAULT FALSE, evaluator_key TEXT NOT NULL, UNIQUE(rule_id,version), CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE risk_policy_versions (policy_version_id UUID PRIMARY KEY, policy_id UUID NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL, account_id UUID NOT NULL, market TEXT NOT NULL, required_scopes JSONB NOT NULL, effective_from DATE NOT NULL, effective_to DATE, owner TEXT NOT NULL, max_input_age_seconds INTEGER NOT NULL CHECK(max_input_age_seconds>=0), UNIQUE(policy_id,version));
CREATE TABLE risk_policy_rule_bindings (policy_version_id UUID NOT NULL REFERENCES risk_policy_versions(policy_version_id), rule_version_id UUID NOT NULL REFERENCES risk_rule_versions(version_id), position INTEGER NOT NULL, PRIMARY KEY(policy_version_id,rule_version_id));
CREATE TABLE risk_check_runs (run_id UUID PRIMARY KEY, account_id UUID NOT NULL, object_id UUID NOT NULL, policy_version_id UUID NOT NULL REFERENCES risk_policy_versions(policy_version_id), stage TEXT NOT NULL, decision_at TIMESTAMPTZ NOT NULL, input_hash TEXT UNIQUE NOT NULL, status TEXT NOT NULL, decision TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, error TEXT);
CREATE TABLE risk_check_results (result_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES risk_check_runs(run_id), rule_version_id UUID NOT NULL REFERENCES risk_rule_versions(version_id), object_id UUID NOT NULL, scope TEXT NOT NULL, metric TEXT NOT NULL, observed JSONB NOT NULL, threshold JSONB NOT NULL, operator TEXT NOT NULL, severity TEXT NOT NULL, outcome TEXT NOT NULL, explanation TEXT NOT NULL, evaluated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE risk_exceptions (exception_id UUID PRIMARY KEY, result_id UUID NOT NULL REFERENCES risk_check_results(result_id), rule_version_id UUID NOT NULL REFERENCES risk_rule_versions(version_id), scope TEXT NOT NULL, requested_by TEXT NOT NULL, approved_by TEXT NOT NULL, reason TEXT NOT NULL, approved_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL CHECK(expires_at>approved_at), status TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=0));
CREATE TABLE risk_alerts (alert_id UUID PRIMARY KEY, account_id UUID NOT NULL, object_id UUID NOT NULL, result_id UUID NOT NULL REFERENCES risk_check_results(result_id), rule_version_id UUID NOT NULL REFERENCES risk_rule_versions(version_id), scope TEXT NOT NULL, observation_window TEXT NOT NULL, dedupe_key TEXT UNIQUE NOT NULL, status TEXT NOT NULL, opened_at TIMESTAMPTZ NOT NULL, version INTEGER NOT NULL CHECK(version>=0), acknowledged_by TEXT, acknowledged_at TIMESTAMPTZ, escalated_to TEXT, resolved_at TIMESTAMPTZ, resolution_evidence TEXT);
CREATE TABLE risk_events (event_id UUID PRIMARY KEY, event_type TEXT NOT NULL, account_id UUID NOT NULL, object_id UUID NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, payload JSONB NOT NULL);
